    submit_checkin_and_order: "Հաստատել այցը և ստեղծել պատվեր",
    ops_effort_title: "Ինչքան է տևում պատվեր անելը",
    ops_effort_info: "Պատվերի էկրանը բացելուց մինչև «Պահպանել»՝ միջին ժամանակը և սեղմումների քանակը՝ չափված վաճառողների հեռախոսներում (այս հնարավորությունից հետո արված պատվերներ)։ Համեմատվում է նախորդ ժամանակահատվածի հետ։ «Սովորական» և «Կրկնել» դյուրանցումները, եթե հստակ ավելի արագ չեն կամ դրանցից չեն օգտվում, կարելի է հանել։",
    ops_sec: "վրկ",
