    vol_info_1: "Աղբյուրը՝ Excel-ի պատվերների տողերը (հաշիվ-ապրանքագրված վաճառք), որ բոտը համաժամեցնում է։ Այսօրվա վաճառքը երևում է Excel-ի հաջորդ համաժամեցումից հետո. հավելվածում արված, բայց Excel-ում դեռ չեղած պատվերները ցույց են տրվում առանձին և երբեք չեն գումարվում։",
    vol_info_2: "Լիտր = տարայի չափ × քանակ (վերադարձները բացասական են)։ Ուղղություն = վաճառքը կատարած ուղղությունը (տողի Sales_Rep). առաջին համաժամեցումից առաջ օգտագործվում է հաճախորդի ուղղությունը։ Ներքին պահեստային հաշիվը (ERP-ից առաջվա դուրսգրումներ) վաճառք չէ և չի հաշվվում։",
    vol_info_3: "Այս հաշվետվությունը ցույց է տալիս միայն լիտրեր. գումարներն ու մարժան կլինեն առանձին հաշվետվության մեջ։ Վաճառքի մենեջերը տեսնում է միայն իր հաճախորդներին։",
