    rps_info_auto_1: "KAD-ը վերցնում է յուրաքանչյուր վաճառքի մենեջերի սեփական հաճախորդներին (չայցելվող ուղղությունները՝ KF/CAS/CVO/PCO/OEM, չեն մտնում) և յուրաքանչյուրին դնում է ճիշտ մեկ շաբաթվա օրվա վրա։",
    rps_info_auto_2: "Լրիվ օրը ստանում է լրիվ բաժին, կես օրը՝ կեսը։ Իրար մոտ հաճախորդները հայտնվում են նույն օրվա մեջ և դասավորվում են երթևեկության հարմար հերթականությամբ, որպեսզի ճանապարհը կարճ լինի։",
    rps_info_auto_3: "Պլանը միայն նախագիծ է. կարող եք փոխել օրերը, պահպանել որպես նոր պլան և ակտիվացնել, երբ պատրաստ է։ Մենեջերները այն տեսնում են միայն ակտիվացնելուց հետո։",
