    rps_info_edit_1: "Սեղմեք շաբաթվա օրվա վրա՝ տեսնելու այդ օրվա հաճախորդներին այցի հերթականությամբ, իսկ հաճախորդի վրա՝ մեկ այլ օր տեղափոխելու համար։",
