    pl_levels_info: "<ul><li><b>Հեռանկար չկա</b> - այս պահին գրեթե իրական հնարավորություն չկա (կեղծ Castrol, սեփական ներմուծում, լրիվ կապված է այլ մատակարարի հետ, կրկնվող մերժումներ)։ Հաճախորդը մնում է ցանկում և կարող է վերագնահատվել։</li><li><b>Ցածր հեռանկար</b> - որոշակի հնարավորություն կա, բայց ցածր՝ շատ փոքր ծավալ, թույլ հետաքրքրություն, ուժեղ մրցակից, մեծ գնային տարբերություն։</li><li><b>Իրական հեռանկար</b> - սովորական որակավորված հնարավոր հաճախորդ՝ վաճառում կամ օգտագործում է յուղեր, պատրաստ է խոսել։</li><li><b>Բարձր հեռանկար</b> - լավ ծավալ, որոշում կայացնողը ներգրավված է, համեմատում է առաջարկները․ մոտ է առաջին պատվերին (գին կամ նմուշ է խնդրել, բանակցում է պայմանների շուրջ)։</li></ul>",
